+                            fail: function (d, c) { finish(code('PKG', c)); }, complete: function () {
+                                if (finished || !live()) { return; } mark('PKG'); fingerprint();
+                            }});
+                    } else { fingerprint(); }
+                } catch (e) { finish('CONFIG_UNAVAILABLE'); }
+            }
+            function subscribe() {
+                if (finished || !live()) { return; }
