+                    if (!bus || typeof bus.subscribeMsg !== 'function' || typeof bus.sendMsg !== 'function' || typeof bus.unsubscribeMsg !== 'function') { finish('BUS_UNAVAILABLE'); return; }
+                    configure();
+                }});
+            } catch (e) { finish('VERSION_UNAVAILABLE'); }
+        },
